CREATE TABLE api_keys ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, scope VARCHAR(8) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, expires_at DATETIME, blocked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE auth_sessions ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, account_id INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, ip VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, uid VARCHAR(32) DEFAULT '' NOT NULL, remember BOOLEAN DEFAULT 1 NOT NULL, stage VARCHAR(8) DEFAULT 'full' NOT NULL, second_factor_by_provider BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE VIRTUAL TABLE book_fts USING fts5(title, original, people, series, description, ids, tokenize = 'unicode61 remove_diacritics 2', content = '', contentless_delete = 1);
CREATE TABLE bookmarks ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, locator VARCHAR(1000) NOT NULL, fraction FLOAT DEFAULT 0 NOT NULL, chapter_title VARCHAR(300) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, note VARCHAR(500) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, edition_id, locator), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE chapters ( id INTEGER NOT NULL, edition_id INTEGER NOT NULL, number INTEGER NOT NULL, title VARCHAR(300) NOT NULL, start_ms INTEGER DEFAULT 0 NOT NULL, target VARCHAR(500) DEFAULT '' NOT NULL, depth INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE credits ( id INTEGER NOT NULL, person_id INTEGER NOT NULL, work_id INTEGER, edition_id INTEGER, role VARCHAR(12) NOT NULL, position INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), FOREIGN KEY(person_id) REFERENCES people (id) ON DELETE CASCADE, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, revoked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE editions ( id INTEGER NOT NULL, work_id INTEGER NOT NULL, library_id INTEGER NOT NULL, kind VARCHAR(8) NOT NULL, variant VARCHAR(12) DEFAULT '' NOT NULL, variant_uncertain BOOLEAN DEFAULT 0 NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, title VARCHAR(300) NOT NULL, subtitle VARCHAR(300) DEFAULT '' NOT NULL, isbn VARCHAR(20) DEFAULT '' NOT NULL, asin VARCHAR(20) DEFAULT '' NOT NULL, publisher VARCHAR(200) DEFAULT '' NOT NULL, published VARCHAR(10) DEFAULT '' NOT NULL, description TEXT DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, series_name VARCHAR(200) DEFAULT '' NOT NULL, series_id INTEGER, series_pos FLOAT, original_title VARCHAR(300) DEFAULT '' NOT NULL, title_key VARCHAR(300) DEFAULT '' NOT NULL, shelf_key VARCHAR(500) DEFAULT '' NOT NULL, pages INTEGER DEFAULT 0 NOT NULL, duration INTEGER DEFAULT 0 NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, missing_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, original_language VARCHAR(8) DEFAULT '' NOT NULL, overlay JSON, grouped_by VARCHAR(8) DEFAULT '' NOT NULL, PRIMARY KEY (id), FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(series_id) REFERENCES series (id) ON DELETE SET NULL );
CREATE TABLE email_confirmations ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, address VARCHAR(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (account_id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE external_refs ( id INTEGER NOT NULL, work_id INTEGER, edition_id INTEGER, source VARCHAR(16) NOT NULL, kind VARCHAR(8) NOT NULL, "key" VARCHAR(120) NOT NULL, market VARCHAR(8) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (edition_id, source, kind, "key", market), FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE files ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, edition_id INTEGER, role VARCHAR(8) NOT NULL, path VARCHAR(1500) NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, sha256 VARCHAR(64) DEFAULT '' NOT NULL, format VARCHAR(8) NOT NULL, part INTEGER DEFAULT 1 NOT NULL, duration_ms INTEGER DEFAULT 0 NOT NULL, unit VARCHAR(1500) DEFAULT '' NOT NULL, probe JSON, dirty BOOLEAN DEFAULT 0 NOT NULL, missing_at DATETIME, seen_at DATETIME NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, path), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE foreign_books ( id INTEGER NOT NULL, token VARCHAR(24) NOT NULL, ref VARCHAR(80) NOT NULL, title VARCHAR(300) NOT NULL, title_key VARCHAR(300) DEFAULT '' NOT NULL, authors JSON, released VARCHAR(10) DEFAULT '' NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, series VARCHAR(200) DEFAULT '' NOT NULL, series_pos FLOAT, cover_url VARCHAR(500) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, data JSON, enriched_at DATETIME, seen_at DATETIME NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token), UNIQUE (ref) );
CREATE TABLE invites ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE jobs ( id INTEGER NOT NULL, kind VARCHAR(16) NOT NULL, ref INTEGER NOT NULL, payload JSON, state VARCHAR(8) NOT NULL, attempts INTEGER NOT NULL, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, error VARCHAR(300) DEFAULT '' NOT NULL, PRIMARY KEY (id) );
CREATE TABLE libraries ( id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, path VARCHAR(1000) NOT NULL, kind VARCHAR(8) NOT NULL, scan_enabled BOOLEAN DEFAULT 1 NOT NULL, scanned_at DATETIME, retry_at DATETIME, progress_done INTEGER DEFAULT 0 NOT NULL, progress_total INTEGER DEFAULT 0 NOT NULL, report JSON, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (name), UNIQUE (path) );
CREATE TABLE library_members ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "right" VARCHAR(8) NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, user_id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE library_problems ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, path VARCHAR(1500) NOT NULL, reason VARCHAR(32) NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, seen_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, path), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE );
CREATE TABLE list_fetches ( source VARCHAR(16) NOT NULL, market VARCHAR(8) NOT NULL, unit VARCHAR(10) NOT NULL, fetched_at DATETIME, state VARCHAR(8) DEFAULT '' NOT NULL, count INTEGER DEFAULT 0 NOT NULL, error VARCHAR(40) DEFAULT '' NOT NULL, wanted_at DATETIME, PRIMARY KEY (source, market, unit) );
CREATE TABLE lists_cache ( id INTEGER NOT NULL, source VARCHAR(16) NOT NULL, market VARCHAR(8) DEFAULT '' NOT NULL, list VARCHAR(10) NOT NULL, rank INTEGER NOT NULL, ref VARCHAR(80) NOT NULL, foreign_id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, author VARCHAR(300) DEFAULT '' NOT NULL, cover_url VARCHAR(500) DEFAULT '' NOT NULL, released VARCHAR(10) DEFAULT '' NOT NULL, kind VARCHAR(8) DEFAULT 'ebook' NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, fetched_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (source, market, list, rank), FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE );
CREATE TABLE match_queue ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, state VARCHAR(8) NOT NULL, reason VARCHAR(40) DEFAULT '' NOT NULL, proposals JSON, fingerprint VARCHAR(64) DEFAULT '' NOT NULL, decision VARCHAR(10) DEFAULT '' NOT NULL, decided_by INTEGER, decided_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (edition_id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE, FOREIGN KEY(decided_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE oidc_links ( id INTEGER NOT NULL, provider_id INTEGER NOT NULL, subject VARCHAR(255) NOT NULL, account_id INTEGER NOT NULL, issuer VARCHAR(500) NOT NULL, email VARCHAR(320), created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), UNIQUE (provider_id, subject), UNIQUE (provider_id, account_id), FOREIGN KEY(provider_id) REFERENCES oidc_providers (id) ON DELETE CASCADE, FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE oidc_providers ( id INTEGER NOT NULL, slug VARCHAR(40) NOT NULL, label VARCHAR(64) NOT NULL, issuer VARCHAR(500) NOT NULL, client_id VARCHAR(255) NOT NULL, client_secret_enc TEXT NOT NULL, scopes VARCHAR(500) NOT NULL, enabled BOOLEAN NOT NULL, auto_create BOOLEAN NOT NULL, trusts_second_factor BOOLEAN NOT NULL, managed VARCHAR(20) NOT NULL, position INTEGER NOT NULL, redirect_path VARCHAR(300) NOT NULL, registered_redirect VARCHAR(500) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (slug) );
CREATE TABLE passkeys ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, credential_id BLOB NOT NULL, public_key BLOB NOT NULL, sign_count INTEGER NOT NULL, name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE password_resets ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE people ( id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, sort_name VARCHAR(200) NOT NULL, "key" VARCHAR(200) NOT NULL, PRIMARY KEY (id), UNIQUE ("key") );
CREATE TABLE progress ( user_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, locator VARCHAR(1000) NOT NULL, fraction FLOAT DEFAULT 0 NOT NULL, unit VARCHAR(8) DEFAULT 'chapter' NOT NULL, chapter INTEGER DEFAULT 0 NOT NULL, chapter_count INTEGER DEFAULT 0 NOT NULL, chapter_title VARCHAR(300) DEFAULT '' NOT NULL, device_key VARCHAR(40) DEFAULT '' NOT NULL, device VARCHAR(80) DEFAULT '' NOT NULL, moved_at DATETIME NOT NULL, received_at DATETIME NOT NULL, PRIMARY KEY (user_id, edition_id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE push_devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, endpoint_key VARCHAR(64) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), CONSTRAINT uq_push_devices_uid UNIQUE (uid), CONSTRAINT uq_push_devices_user_endpoint UNIQUE (user_id, endpoint_key), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE search_entries ( edition_id INTEGER NOT NULL, digest VARCHAR(40) NOT NULL, PRIMARY KEY (edition_id), FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE series ( id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, "key" VARCHAR(200) NOT NULL, PRIMARY KEY (id), UNIQUE ("key") );
CREATE TABLE settings ( "key" VARCHAR(64) NOT NULL, value JSON, PRIMARY KEY ("key") );
CREATE TABLE source_cache ( id INTEGER NOT NULL, source VARCHAR(16) NOT NULL, "key" VARCHAR(300) NOT NULL, value JSON, fetched_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (source, "key") );
CREATE TABLE source_state ( source VARCHAR(16) NOT NULL, tokens FLOAT DEFAULT 0 NOT NULL, refilled_at DATETIME, day VARCHAR(10) DEFAULT '' NOT NULL, day_count INTEGER DEFAULT 0 NOT NULL, last_ok_at DATETIME, last_error VARCHAR(40) DEFAULT '' NOT NULL, last_error_at DATETIME, fail_count INTEGER DEFAULT 0 NOT NULL, blocked_until DATETIME, state VARCHAR(16) DEFAULT '' NOT NULL, PRIMARY KEY (source) );
CREATE TABLE users ( id INTEGER NOT NULL, name VARCHAR(64) NOT NULL, display_name VARCHAR(80) NOT NULL, whats_new_seen VARCHAR(32) NOT NULL, role VARCHAR(16) NOT NULL, sign_in VARCHAR(16) NOT NULL, password_hash VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, email_confirmed_at DATETIME, email_from_provider BOOLEAN DEFAULT 0 NOT NULL, language VARCHAR(16) NOT NULL, profile JSON, created_at DATETIME NOT NULL, last_seen_at DATETIME, failed_logins INTEGER NOT NULL, locked_until DATETIME, blocked_at DATETIME, totp_secret_enc TEXT NOT NULL, totp_recovery TEXT NOT NULL, totp_last_step INTEGER NOT NULL, avatar BLOB, avatar_at DATETIME, signed_in_before BOOLEAN DEFAULT 0 NOT NULL, passkey_handle VARCHAR(64) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
CREATE TABLE wishlist ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, foreign_id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, author VARCHAR(300) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, added_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, foreign_id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE );
CREATE TABLE works ( id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, original_title VARCHAR(300) DEFAULT '' NOT NULL, original_language VARCHAR(8) DEFAULT '' NOT NULL, description TEXT DEFAULT '' NOT NULL, year INTEGER, genre VARCHAR(16) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, series_id INTEGER, series_pos FLOAT, pages INTEGER DEFAULT 0 NOT NULL, pattern INTEGER DEFAULT 0 NOT NULL, tall FLOAT DEFAULT (0.5) NOT NULL, gold BOOLEAN DEFAULT 0 NOT NULL, "key" VARCHAR(300) DEFAULT '' NOT NULL, main_key VARCHAR(300) DEFAULT '' NOT NULL, original_key VARCHAR(300) DEFAULT '' NOT NULL, added_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(series_id) REFERENCES series (id) ON DELETE SET NULL );
CREATE INDEX ix_api_keys_account_id ON api_keys (account_id);
CREATE INDEX ix_auth_sessions_account_id ON auth_sessions (account_id);
CREATE INDEX ix_bookmarks_person ON bookmarks (user_id, edition_id);
CREATE INDEX ix_chapters_edition ON chapters (edition_id, number);
CREATE INDEX ix_credits_edition ON credits (edition_id);
CREATE INDEX ix_credits_person ON credits (person_id);
CREATE INDEX ix_credits_work ON credits (work_id);
CREATE INDEX ix_devices_account_id ON devices (account_id);
CREATE INDEX ix_editions_isbn ON editions (isbn);
CREATE INDEX ix_editions_library_id ON editions (library_id);
CREATE INDEX ix_editions_series_id ON editions (series_id);
CREATE INDEX ix_editions_work_id ON editions (work_id);
CREATE INDEX ix_external_refs_edition_id ON external_refs (edition_id);
CREATE INDEX ix_external_refs_key ON external_refs (source, kind, "key");
CREATE INDEX ix_external_refs_work_id ON external_refs (work_id);
CREATE INDEX ix_files_dirty ON files (library_id, dirty);
CREATE INDEX ix_files_edition_id ON files (edition_id);
CREATE INDEX ix_files_library_id ON files (library_id);
CREATE INDEX ix_files_unit ON files (library_id, unit);
CREATE INDEX ix_foreign_books_seen ON foreign_books (seen_at);
CREATE INDEX ix_foreign_books_title ON foreign_books (title_key);
CREATE INDEX ix_jobs_state ON jobs (state, id);
CREATE INDEX ix_library_members_library_id ON library_members (library_id);
CREATE INDEX ix_library_members_user_id ON library_members (user_id);
CREATE INDEX ix_library_problems_library_id ON library_problems (library_id);
CREATE INDEX ix_lists_cache_foreign ON lists_cache (foreign_id);
CREATE INDEX ix_lists_cache_list ON lists_cache (list, market);
CREATE INDEX ix_match_queue_library ON match_queue (library_id, state);
CREATE INDEX ix_oidc_links_account_id ON oidc_links (account_id);
CREATE INDEX ix_oidc_links_provider_id ON oidc_links (provider_id);
CREATE INDEX ix_passkeys_user_id ON passkeys (user_id);
CREATE INDEX ix_password_resets_account_id ON password_resets (account_id);
CREATE INDEX ix_progress_edition ON progress (edition_id);
CREATE INDEX ix_push_devices_user_id ON push_devices (user_id);
CREATE INDEX ix_source_cache_expires ON source_cache (expires_at);
CREATE INDEX ix_wishlist_person ON wishlist (user_id, added_at);
CREATE INDEX ix_works_added_at ON works (added_at);
CREATE INDEX ix_works_key ON works ("key");
CREATE INDEX ix_works_main_key ON works (main_key);
CREATE INDEX ix_works_original_key ON works (original_key);
CREATE INDEX ix_works_series_id ON works (series_id);
CREATE UNIQUE INDEX uq_auth_sessions_uid ON auth_sessions (uid);
CREATE UNIQUE INDEX uq_devices_uid ON devices (uid);
CREATE UNIQUE INDEX uq_jobs_waiting ON jobs (kind, ref) WHERE state = 'queued';
CREATE UNIQUE INDEX uq_passkeys_credential ON passkeys (credential_id);
CREATE UNIQUE INDEX uq_passkeys_uid ON passkeys (uid);
CREATE TRIGGER editions_search_gone AFTER DELETE ON editions BEGIN DELETE FROM book_fts WHERE rowid = old.id; END;
